static z_t62_t z_t78_concat(
    const z_t78_t* self, const z_t78_t* other) {
    z_t62_t z = {0};
    uint64_t total = self->size + other->size;
    z.size = total;
    z.capacity = total + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    memcpy(z.data, self->data, self->size);
    memcpy(z.data + self->size, other->data, other->size);
    z.data[total] = '\0';
    return z;
}

static z_t881_t z_t78_indexOf(const z_t78_t* self, const z_t78_t* needle);
